return {["s5off"]={{["speaker"]="kaguya",["portrait"]="kaguya11",["displayName"]="辉夜",["text"]="「虽然印象里浅间净秽山确实是金字塔形，不过我记得不是在沙漠啊！」",["sourceParagraph"]=3,["line"]=1,["rows"]={"「虽然印象里浅间净秽山确实是金字塔形，不过我记得","不是在沙漠啊！」"},["hideOtherPortrait"]=true},{["speaker"]="kaguya",["portrait"]="kaguya5",["displayName"]="辉夜",["text"]="「对深闺的公主（的头皮）来说，刺激是不是强了点儿？」",["sourceParagraph"]=4,["line"]=2,["rows"]={"「对深闺的公主（的头皮）来说，刺激是不是强了点儿","？」"},["hideOtherPortrait"]=true},{["speaker"]="horou",["portrait"]="horou2",["displayName"]="鸟澄珠乌",["text"]="「终于来人了。我听说幻想乡的人类性子都很急躁」",["sourceParagraph"]=6,["line"]=3,["rows"]={"「终于来人了。我听说幻想乡的人类性子都很急躁」"},["hideOtherPortrait"]=true}},["s5pre"]={{["speaker"]="horou",["portrait"]="horou2",["displayName"]="鸟澄珠乌",["text"]="「你倒是……」",["sourceParagraph"]=8,["line"]=1,["rows"]={"「你倒是……」"}},{["speaker"]="horou",["portrait"]="horou10",["displayName"]="鸟澄珠乌",["text"]="「？」",["sourceParagraph"]=9,["line"]=2,["rows"]={"「？」"}},{["speaker"]="kaguya",["portrait"]="kaguya11",["displayName"]="辉夜",["text"]="「啊，你是先前那个要停止时间的朱鹭什么来着」",["sourceParagraph"]=11,["line"]=3,["rows"]={"「啊，你是先前那个要停止时间的朱鹭什么来着」"}},{["speaker"]="horou",["portrait"]="horou9",["displayName"]="珠乌",["text"]="「真是失礼，那我就再说一次。我叫珠乌，是最强大的朱鹭。」",["sourceParagraph"]=13,["line"]=4,["rows"]={"「真是失礼，那我就再说一次。我叫珠乌，是最强大的","朱鹭。」"}},{["speaker"]="horou",["portrait"]="horou1",["displayName"]="珠乌",["text"]="「真没想到身为月人的你居然大胆到闯进这里来。那我就替被你们迫害的阿梨夜酱再教训你一次！」",["sourceParagraph"]=14,["line"]=5,["rows"]={"「真没想到身为月人的你居然大胆到闯进这里来。那我","就替被你们迫害的阿梨夜酱再教训你一次！」"}},{["speaker"]="kaguya",["portrait"]="kaguya11",["displayName"]="辉夜",["text"]="「这个名字，之前好像在哪听说过？」",["sourceParagraph"]=17,["line"]=6,["rows"]={"「这个名字，之前好像在哪听说过？」"}}},["s5mid"]={{["speaker"]="horou",["portrait"]="horou2",["displayName"]="珠乌",["text"]="「有了阿梨夜酱的力量，这次我绝不会轻易输给你！」",["sourceParagraph"]=21,["line"]=1,["rows"]={"「有了阿梨夜酱的力量，这次我绝不会轻易输给你！」"}},{["speaker"]="horou",["portrait"]="horou2",["displayName"]="珠乌",["text"]="「你的时间所剩不多了！」",["sourceParagraph"]=22,["line"]=2,["rows"]={"「你的时间所剩不多了！」"}}},["s5post"]={{["speaker"]="horou",["portrait"]="horou3",["displayName"]="珠乌",["text"]="「居然又输了吗……对不起，阿梨夜酱……」",["sourceParagraph"]=27,["line"]=1,["rows"]={"「居然又输了吗……对不起，阿梨夜酱……」"}},{["speaker"]="kaguya",["portrait"]="kaguya21",["displayName"]="辉夜",["text"]="「都说了我不是来找你麻烦的了。」",["sourceParagraph"]=30,["line"]=2,["rows"]={"「都说了我不是来找你麻烦的了。」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["displayName"]="辉夜",["text"]="「现在能不能告诉我到底发生了什么？」",["sourceParagraph"]=31,["line"]=3,["rows"]={"「现在能不能告诉我到底发生了什么？」"}},{["speaker"]="horou",["portrait"]="horou2",["displayName"]="珠乌",["text"]="「这里是你们用来聚集并净化外界污秽的装置。」",["sourceParagraph"]=33,["line"]=4,["rows"]={"「这里是你们用来聚集并净化外界污秽的装置。」"}},{["speaker"]="horou",["portrait"]="horou10",["displayName"]="珠乌",["text"]="「你们这些月人非要抓走阿梨夜酱的朋友，又让她去做什么炒作。」",["sourceParagraph"]=35,["line"]=5,["rows"]={"「你们这些月人非要抓走阿梨夜酱的朋友，又让她去做","什么炒作。」"}},{["speaker"]="horou",["portrait"]="horou3",["displayName"]="珠乌",["text"]="「大量积压的污秽逸散出去，影响了幻想乡的认知，让妖精和弱小的妖怪们都只会复读无意义的语言。聚集的污秽甚至实体化成了异形的怪物，突破了这里的封印。」",["sourceParagraph"]=37,["line"]=6,["rows"]={"「大量积压的污秽逸散出去，影响了幻想乡的认知，让","妖精和弱小的妖怪们都只会复读无意义的语言。聚集的"}},{["speaker"]="horou",["portrait"]="horou3",["displayName"]="珠乌",["text"]="「大量积压的污秽逸散出去，影响了幻想乡的认知，让妖精和弱小的妖怪们都只会复读无意义的语言。聚集的污秽甚至实体化成了异形的怪物，突破了这里的封印。」",["sourceParagraph"]=37,["line"]=6,["rows"]={"污秽甚至实体化成了异形的怪物，突破了这里的封印。","」"}},{["speaker"]="horou",["portrait"]="horou6",["displayName"]="珠乌",["text"]="「我来这里就是为了帮她看家，把这里变成与世隔绝的沙漠，减轻污秽外溢的影响。」",["sourceParagraph"]=39,["line"]=7,["rows"]={"「我来这里就是为了帮她看家，把这里变成与世隔绝的","沙漠，减轻污秽外溢的影响。」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["displayName"]="辉夜",["text"]="「听起来情况不容乐观啊，那个怪物跑到哪里去了？」",["sourceParagraph"]=42,["line"]=8,["rows"]={"「听起来情况不容乐观啊，那个怪物跑到哪里去了？」"}},{["speaker"]="horou",["portrait"]="horou2",["displayName"]="珠乌",["text"]="「它跑到妖怪之山顶上去了」",["sourceParagraph"]=44,["line"]=9,["rows"]={"「它跑到妖怪之山顶上去了」"}},{["speaker"]="horou",["portrait"]="horou2",["displayName"]="珠乌",["text"]="「所有听过它声音的妖精都只会发出和它一样可怕的笑声。」",["sourceParagraph"]=45,["line"]=10,["rows"]={"「所有听过它声音的妖精都只会发出和它一样可怕的笑","声。」"}},{["speaker"]="horou",["portrait"]="horou2",["displayName"]="珠乌",["text"]="「它非常强大，请务必小心。」",["sourceParagraph"]=46,["line"]=11,["rows"]={"「它非常强大，请务必小心。」"}},{["speaker"]="kaguya",["portrait"]="kaguya11",["displayName"]="辉夜",["text"]="「妖怪之山上，那里是守矢神社」",["sourceParagraph"]=49,["line"]=12,["rows"]={"「妖怪之山上，那里是守矢神社」"}},{["speaker"]="kaguya",["portrait"]="kaguya14",["displayName"]="辉夜",["text"]="「哦对了，其实我早就不是月球人了。」",["sourceParagraph"]=50,["line"]=13,["rows"]={"「哦对了，其实我早就不是月球人了。」"}}}}
